export const fetchDiscoverFeed = () => fetchManifest<RacePicDiscoverImage[]>('/manifests/discover.json', z.array(discoverImageSchema));

export type RacePicDiscoverIndex = { total: number; pageCount: number; pageSize: number };
const discoverIndexSchema = z.object({ total: z.number().int().nonnegative(), pageCount: z.number().int().nonnegative(), pageSize: z.number().int().positive() });
export const fetchDiscoverIndex = () => fetchManifest<RacePicDiscoverIndex>('/manifests/discover-index.json', discoverIndexSchema);
export const fetchDiscoverPage = (page: number) =>
  fetchManifest<RacePicDiscoverImage[]>(`/manifests/discover-pages/${Math.max(1, Math.trunc(page))}.json`, z.array(discoverImageSchema));

export type RacePicImageDetail = {
  image: RacePicImage;
  eventSlug: string;
  eventTitle: string;
  participants: RacePicParticipant[];
  relatedImages: RacePicImage[];
};
const imageDetailSchema = z.object({
  image: imageSchema, eventSlug: z.string(), eventTitle: z.string(), participants: z.array(participantSchema), relatedImages: z.array(imageSchema)
});
export const fetchImageDetail = (eventSlug: string, imageId: string) =>
  fetchManifest<RacePicImageDetail>(`/manifests/${encodeURIComponent(eventSlug)}/i/${encodeURIComponent(imageId)}.json`, imageDetailSchema);

export type RacePicSearchIndexEntry = {
  participantKey: string;
  eventSlug: string;
  eventTitle: string;
  startNumber: string;
  displayName: string;
  make: string | null;
  model: string | null;
  className: string;
};
const searchIndexEntrySchema = z.object({
  participantKey: z.string(), eventSlug: z.string(), eventTitle: z.string(), startNumber: z.string(), displayName: z.string(),
  make: z.string().nullable(), model: z.string().nullable(), className: z.string()
});

export const fetchSearchIndex = () => fetchManifest<RacePicSearchIndexEntry[]>('/manifests/search-index.json', z.array(searchIndexEntrySchema));

/** Convert a validated relative manifest asset path to an absolute CDN URL. */
export const toCdnUrl = (relativePath: string): string => {
  if (!/^\/(public|manifests)\/[A-Za-z0-9._~!$&'()*+,;=:@%/-]+$/.test(relativePath) || relativePath.includes('..')) {
    throw new RacePicPublicError(400);
  }
  return `${cdnBaseUrl}${relativePath}`;
};

export type DownloadVariant = 'small' | 'medium' | 'large' | 'original';

export type DownloadResult = {
  url: string;
  expiresAt: string;
  attribution: {
    photographerName: string;
    copyrightLine: string | null;
    licenseCode: string;
    licenseTitle: Record<string, string>;
    attributionRequired: boolean;
    attributionTemplate: string | null;
  };
};
const downloadResultSchema = z.object({
  url: z.string().url(),
  expiresAt: z.string(),
  attribution: z.object({
    photographerName: z.string(), copyrightLine: z.string().nullable(), licenseCode: z.string(),
    licenseTitle: z.record(z.string()), attributionRequired: z.boolean(), attributionTemplate: z.string().nullable()
  })
});

export const requestDownload = async (imageId: string, variant: DownloadVariant): Promise<DownloadResult> => {
  if (!configuredEventApiBaseUrl) throw new RacePicPublicError(0);
  const response = await fetch(`${eventApiBaseUrl}/public/racepic/images/${encodeURIComponent(imageId)}/download`, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ variant })
  });
  const payload = await response.json().catch(() => null);
  if (!response.ok || !payload) throw new RacePicPublicError(response.status);
  const parsed = downloadResultSchema.safeParse(payload);
  if (!parsed.success) throw new RacePicPublicError(502);
  return parsed.data as DownloadResult;
};
